"""AI Dev OS Workbench 首页。"""

WORKBENCH_HUB_HTML = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AI Dev OS Workbench</title><style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#121a2f;--line:#263250;--text:#edf2ff;--muted:#95a4c5;--brand:#7c9cff;--good:#45d6a4;--warn:#ffca6a}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top left,#192750 0,#0b1020 42%);color:var(--text);font:14px/1.5 Inter,Segoe UI,sans-serif}.hidden{display:none!important}button,input,textarea,select{font:inherit}.login{min-height:100vh;display:grid;place-items:center}.login-card,.card{background:rgba(18,26,47,.94);border:1px solid var(--line);border-radius:18px;box-shadow:0 18px 60px #0006}.login-card{width:min(420px,calc(100% - 32px));padding:32px}.logo{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,#91a8ff,#7657ff);display:grid;place-items:center;font-weight:800}.brand{display:flex;align-items:center;gap:12px;font-size:18px;font-weight:700}.field{width:100%;padding:12px 14px;background:#0b1225;border:1px solid var(--line);border-radius:10px;color:var(--text);margin:8px 0}.primary,.ghost{border:0;border-radius:10px;padding:10px 14px;cursor:pointer}.primary{background:var(--brand);color:#081020;font-weight:700}.ghost{background:#1c2743;color:var(--text)}.primary:disabled{opacity:.5}.shell{min-height:100vh;display:grid;grid-template-columns:330px 1fr}.sidebar{padding:22px;border-right:1px solid var(--line);background:#0c1326}.sidebar-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.sidebar-actions{display:flex;gap:8px}.stats{color:var(--muted);font-size:12px;margin:12px 0 18px}.project{margin:12px 0}.project-title{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}.project-title h3{margin:0;font-size:13px;color:var(--muted);min-width:0;overflow:hidden;text-overflow:ellipsis}.mini{border:0;background:transparent;color:var(--muted);cursor:pointer;padding:2px 6px}.mini:hover{color:#ff8294}.space{display:block;width:100%;text-align:left;border:1px solid transparent;background:transparent;color:var(--text);padding:10px;border-radius:10px;cursor:pointer}.space:hover,.space.active{background:#17213a;border-color:#334365}.space small{display:block;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.status{float:right;font-size:10px;padding:2px 7px;border-radius:999px;background:#263250}.status.in_progress{color:#07170f;background:var(--good)}.status.done{color:#0e1830;background:#9badd8}.main{padding:26px;min-width:0}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:20px}.top h1{margin:0;font-size:26px}.top p{margin:4px 0 0;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.card{padding:20px}.wide{grid-column:1/-1}.card h2{margin:0 0 12px;font-size:16px}.markdown{white-space:pre-wrap;max-height:330px;overflow:auto;color:#d8e1f7}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.fact{background:#0d1528;border:1px solid #202c49;border-radius:10px;padding:12px}.fact b{display:block;color:var(--muted);font-size:11px;margin-bottom:4px}.empty{color:var(--muted);padding:28px;text-align:center}.modal{position:fixed;inset:0;background:#000a;display:grid;place-items:center}.modal .card{width:min(560px,calc(100% - 32px))}.actions{display:flex;gap:10px;justify-content:flex-end;margin-top:12px}.error{color:#ff8294}.notice{padding:12px;border:1px solid #5b4927;background:#231d13;color:var(--warn);border-radius:10px}.composer textarea{min-height:110px}.run-result{margin-top:10px;color:var(--muted);white-space:pre-wrap}@media(max-width:850px){.shell{display:block}.sidebar{border-right:0;border-bottom:1px solid var(--line)}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.facts{grid-template-columns:1fr}}
</style></head><body>
<section id="login" class="login"><div class="login-card"><div class="brand"><div class="logo">A</div>AI Dev OS Workbench</div><h1>进入需求空间</h1><p>正在建立本机安全连接。</p><input id="token" class="field" type="password" placeholder="访问 Token"><button class="primary" onclick="connect()">连接</button><p id="login-error" class="error"></p></div></section>
<div id="app" class="shell hidden"><aside class="sidebar"><div class="sidebar-head"><div class="brand"><div class="logo">A</div>Workbench</div><div class="sidebar-actions"><button class="ghost" onclick="showProject()">＋ 项目</button><button class="primary" onclick="showCreate()">＋ 需求</button></div></div><div id="counts" class="stats"></div><div id="spaces"></div></aside><main class="main"><header class="top"><div><h1 id="title">需求空间</h1><p id="subtitle">选择一个 Requirement 进入控制面</p></div><button class="ghost" onclick="refreshCatalog()">刷新</button></header><section id="welcome" class="card"><h2>以 Requirement Space 为核心</h2><p>先添加现有项目或创建新项目；一个 Workbench 可以绑定多个项目。进入项目下的 Requirement 后，可以查看稳定事实并启动真实 Agent 执行。</p></section><section id="detail" class="grid hidden"><div class="card wide"><div class="facts" id="facts"></div></div><div class="card"><h2>Intent</h2><div id="intent" class="markdown"></div></div><div class="card"><h2>Acceptance</h2><div id="requirement" class="markdown"></div></div><div class="card"><h2>Progress / Next Action</h2><div id="progress" class="markdown"></div></div><div class="card"><h2>Task / Execution / Verification</h2><div id="execution" class="markdown"></div></div><div class="card wide composer"><h2>开始或继续真实执行</h2><div class="notice">Agent 仅可写入所选项目工作区；审批保持拒绝。发送即明确授权本次项目内开发。</div><textarea id="message" class="field" placeholder="例如：实现当前需求，先交付可运行 Demo，再完成验证。"></textarea><div class="actions"><button id="run" class="primary" onclick="runAgent()">开始 / 继续执行</button></div><div id="run-result" class="run-result"></div></div></section></main></div>
<section id="project-modal" class="modal hidden"><div class="card"><h2>添加工作区项目</h2><label>操作<select id="project-mode" class="field"><option value="add">添加现有项目</option><option value="create">创建新项目</option></select></label><label>项目绝对路径<input id="project-path" class="field" placeholder="例如 D:\code\my-project"></label><div class="notice">添加现有项目会保留全部文件，仅补齐 AI Dev OS 接入文件并绑定到本工作台；创建新项目要求目标目录尚不存在。</div><div class="actions"><button class="ghost" onclick="hideProject()">取消</button><button class="primary" onclick="addProject()">确认并绑定</button></div><p id="project-error" class="error"></p></div></section>
<section id="create" class="modal hidden"><div class="card"><h2>新建 Requirement</h2><label>项目<select id="new-project" class="field"></select></label><label>标题<input id="new-title" class="field" maxlength="200"></label><label>目标<textarea id="new-goal" class="field"></textarea></label><label>验收标准（每行一项）<textarea id="new-acceptance" class="field"></textarea></label><label>复杂度<select id="new-complexity" class="field"><option>normal</option><option>tiny</option><option>complex</option><option>research</option></select></label><div class="actions"><button class="ghost" onclick="hideCreate()">取消</button><button class="primary" onclick="createRequirement()">创建并进入</button></div><p id="create-error" class="error"></p></div></section>
<script>
const AUTH_REQUIRED=__AUTH_REQUIRED__;const state={catalog:null,project:null,requirement:null,activeExecution:null};const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function headers(){const h={'Content-Type':'application/json'};if(AUTH_REQUIRED)h.Authorization='Bearer '+$('token').value;return h}async function api(path,options={}){const r=await fetch(path,{...options,headers:{...headers(),...(options.headers||{})}});let p={};try{p=await r.json()}catch{}if(!r.ok)throw Error(p.error||`HTTP ${r.status}`);return p}
async function connect(){sessionStorage.setItem('ai-dev-os-workbench-token',$('token').value);try{await refreshCatalog();$('login').classList.add('hidden');$('app').classList.remove('hidden')}catch(e){$('login-error').textContent='连接失败：'+e.message}}
async function refreshCatalog(){state.catalog=await api('/api/workbench');renderCatalog()}
function renderCatalog(){const c=state.catalog;$('counts').textContent=`${c.counts.projects} 个项目 · ${c.counts.requirements} 个需求 · ${c.counts.active} 个活动需求`;$('new-project').innerHTML=c.projects.filter(p=>p.status==='active').map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('spaces').innerHTML=c.projects.map(p=>`<div class="project"><div class="project-title"><h3 title="${esc(p.path)}">${esc(p.name)} · ${esc(p.status)}</h3><button class="mini" title="仅解除绑定，不删除文件" onclick="removeProject('${encodeURIComponent(p.id)}')">解除绑定</button></div>${p.requirements.map(r=>`<button class="space ${state.project===p.id&&state.requirement===r.id?'active':''}" onclick="openSpace('${encodeURIComponent(p.id)}','${r.id}')"><span class="status ${esc(r.status)}">${esc(r.status)}</span><b>${esc(r.id)}</b><small>${esc(r.title)}</small></button>`).join('')||'<div class="empty">暂无需求</div>'}</div>`).join('')}
async function openSpace(project,id){state.project=decodeURIComponent(project);state.requirement=id;renderCatalog();const d=await api(`/api/projects/${encodeURIComponent(state.project)}/requirements/${id}`),w=d.workspace,p=d.projection||{},m=w.meta||{},executions=p.executions||[],tasks=p.task_graph?.nodes||[],verification=p.verification||[];state.activeExecution=executions.find(x=>['running','waiting'].includes(x.status))||null;$('welcome').classList.add('hidden');$('detail').classList.remove('hidden');$('title').textContent=`${id} · ${m.title||''}`;$('subtitle').textContent=d.project_name||state.project;$('facts').innerHTML=[['状态',m.status],['阶段',p.requirement_space?.phase],['复杂度',m.complexity],['活动 Execution',executions.filter(x=>['queued','starting','running','waiting'].includes(x.status)).length],['阻塞',(p.blockers||[]).length],['Git',p.git?.clean?'干净':'有修改']].map(x=>`<div class="fact"><b>${esc(x[0])}</b>${esc(x[1]??'—')}</div>`).join('');$('intent').textContent=w.intent;$('requirement').textContent=w.requirement;$('progress').textContent=w.state;const taskRows=tasks.map(x=>`${x.task_id} · ${x.status}`).join('\n')||'无',executionRows=executions.map(x=>`${x.id} · ${x.runtime_id||x.runtime} · ${x.status} · ${x.task_id}`).join('\n')||'无',verificationRows=verification.map(x=>`${x.suite_id||x.receipt_id} · ${x.status}`).join('\n')||'无';$('execution').textContent=`Tasks\n${taskRows}\n\nExecutions / Agents\n${executionRows}\n\nVerification\n${verificationRows}\n\n下一步\n${(p.next_actions||[]).join('\n')||'未记录'}`;$('run').textContent=state.activeExecution?'继续 Execution '+state.activeExecution.id:'开始真实 Execution'}
function showCreate(){$('create').classList.remove('hidden')}function hideCreate(){$('create').classList.add('hidden')}
function showProject(){$('project-modal').classList.remove('hidden')}function hideProject(){$('project-modal').classList.add('hidden')}
async function addProject(){try{const path=$('project-path').value.trim(),mode=$('project-mode').value;await api('/api/projects',{method:'POST',body:JSON.stringify({path,mode})});hideProject();$('project-path').value='';await refreshCatalog()}catch(e){$('project-error').textContent=e.message}}
async function removeProject(project){const id=decodeURIComponent(project),item=state.catalog.projects.find(p=>p.id===id);if(!confirm(`解除 ${(item&&item.name)||id} 的工作台绑定？项目文件和需求不会删除。`))return;try{await api(`/api/projects/${project}`,{method:'DELETE'});if(state.project===id){state.project=null;state.requirement=null;$('detail').classList.add('hidden');$('welcome').classList.remove('hidden')}await refreshCatalog()}catch(e){alert('解除绑定失败：'+e.message)}}
async function createRequirement(){try{const project=$('new-project').value,title=$('new-title').value.trim(),goal=$('new-goal').value.trim(),acceptance=$('new-acceptance').value.split('\n').map(x=>x.trim()).filter(Boolean),complexity=$('new-complexity').value;const r=await api(`/api/projects/${encodeURIComponent(project)}/requirements`,{method:'POST',body:JSON.stringify({title,goal,acceptance,complexity})});hideCreate();await refreshCatalog();await openSpace(encodeURIComponent(project),r.requirement_id)}catch(e){$('create-error').textContent=e.message}}
async function runAgent(){const message=$('message').value.trim();if(!message)return;const b=$('run');b.disabled=true;$('run-result').textContent=state.activeExecution?'正在恢复原 Execution Session…':'正在创建一等 Execution 并启动真实 Runtime…';try{const payload={message,command_id:crypto.randomUUID()};if(state.activeExecution)payload.execution_id=state.activeExecution.id;const r=await api(`/api/projects/${encodeURIComponent(state.project)}/requirements/${state.requirement}/message`,{method:'POST',body:JSON.stringify(payload)});$('run-result').textContent=`${r.status}：Execution ${r.execution_id||'—'} · Session ${r.session_id||'—'}`;await openSpace(encodeURIComponent(state.project),state.requirement)}catch(e){$('run-result').textContent='执行失败：'+e.message}finally{b.disabled=false}}
const hash=new URLSearchParams(location.hash.slice(1)),bootstrap=hash.get('token');if(!AUTH_REQUIRED){connect()}else if(bootstrap){$('token').value=bootstrap;history.replaceState(null,'',location.pathname);connect()}else{ $('token').value=sessionStorage.getItem('ai-dev-os-workbench-token')||'';if($('token').value)connect() }$('token').addEventListener('keydown',e=>{if(e.key==='Enter')connect()});
</script></body></html>"""
